1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface QuoteItem {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: 'quote';
14	  items: QuoteItem[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: 'claim';
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE = 0.1;
41	
42	const BASE_PREMIUMS: Record<string, number> = {
43	  sword: 100,
44	  amulet: 60,
45	  staff: 80,
46	  potion: 40,
47	};
48	
49	const COMPONENT_BASE_PREMIUM = 25;
50	const COMPONENT_TYPES = ['rune', 'moonstone'];
51	
52	function isComponent(type: string): boolean {
53	  return COMPONENT_TYPES.includes(type);
54	}
55	
56	function isInsurable(type: string): boolean {
57	  return isComponent(type) || type in BASE_PREMIUMS;
58	}
59	
60	function basePremiumOf(item: QuoteItem): number {
61	  return isComponent(item.type)
62	    ? COMPONENT_BASE_PREMIUM
63	    : BASE_PREMIUMS[item.type];
64	}
65	
66	const BLOCK_SIZE = 3;
67	const BLOCK_BASE_PREMIUM = 60;
68	
69	/**
70	 * Components of the same type are priced per type: exactly {@link BLOCK_SIZE}
71	 * alike components form a block at a reduced base premium.
72	 */
73	function componentsBasePremium(components: QuoteItem[]): number {
74	  const countsByType = new Map<string, number>();
75	  for (const component of components) {
76	    countsByType.set(
77	      component.type,
78	      (countsByType.get(component.type) ?? 0) + 1,
79	    );
80	  }
81	
82	  let base = 0;
83	  for (const count of countsByType.values()) {
84	    base +=
85	      count === BLOCK_SIZE
86	        ? BLOCK_BASE_PREMIUM
87	        : count * COMPONENT_BASE_PREMIUM;
88	  }
89	  return base;
90	}
91	
92	const CURSE_SURCHARGE = 0.5;
93	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
94	const HIGH_ENCHANTMENT_LEVEL = 5;
95	
96	/**
97	 * Item-specific surcharges are charged on the base premium of the affected
98	 * item alone, never on the policy total.
99	 */
100	function itemSurcharges(item: QuoteItem): number {
101	  const base = basePremiumOf(item);
102	  let surcharge = 0;
103	  if (item.cursed) surcharge += base * CURSE_SURCHARGE;
104	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL) {
105	    surcharge += base * HIGH_ENCHANTMENT_SURCHARGE;
106	  }
107	  return surcharge;
108	}
109	
110	const LOYALTY_DISCOUNT = 0.2;
111	const LOYALTY_YEARS = 2;
112	
113	const FOLLOW_UP_DISCOUNT = 0.15;
114	
115	function quotePremium(
116	  items: QuoteItem[],
117	  customer: Customer,
118	  isFollowUpContract: boolean,
119	): number {
120	  for (const item of items) {
121	    if (!isInsurable(item.type)) {
122	      throw new Error(`The MHPCO does not insure items of type "${item.type}"`);
123	    }
124	  }
125	
126	  const mainItems = items.filter((item) => !isComponent(item.type));
127	  const components = items.filter((item) => isComponent(item.type));
128	
129	  const policyBase =
130	    mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0) +
131	    componentsBasePremium(components);
132	  const surcharges = items.reduce((sum, item) => sum + itemSurcharges(item), 0);
133	
134	  const loyalty =
135	    customer.yearsWithMHPCO >= LOYALTY_YEARS ? policyBase * LOYALTY_DISCOUNT : 0;
136	
137	  const followUp = isFollowUpContract ? policyBase * FOLLOW_UP_DISCOUNT : 0;
138	
139	  return Math.ceil(
140	    policyBase +
141	      surcharges -
142	      loyalty +
143	      policyBase * FIRST_INSURANCE_SURCHARGE -
144	      followUp +
145	      PROCESSING_FEE,
146	  );
147	}
148	
149	const INSURANCE_VALUES: Record<string, number> = {
150	  sword: 1000,
151	  amulet: 600,
152	  staff: 800,
153	  potion: 400,
154	};
155	
156	const COMPONENT_INSURANCE_VALUE = 250;
157	const DEDUCTIBLE = 100;
158	const CAP_FACTOR = 2;
159	
160	function insuranceValueOf(item: QuoteItem): number {
161	  return isComponent(item.type)
162	    ? COMPONENT_INSURANCE_VALUE
163	    : INSURANCE_VALUES[item.type];
164	}
165	
166	interface Policy {
167	  items: QuoteItem[];
168	  remainingCap: number;
169	}
170	
171	const REIMBURSED_ENCHANTMENT_LEVEL = 8;
172	const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
173	
174	/**
175	 * The reimbursement clauses reduce the damage amount; the deductible is
176	 * subtracted afterwards, once per damaged item.
177	 */
178	function payoutFor(damage: Damage, item: QuoteItem): number {
179	  const reimbursed =
180	    (item.enchantment ?? 0) >= REIMBURSED_ENCHANTMENT_LEVEL
181	      ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT
182	      : damage.amount;
183	
184	  return reimbursed - DEDUCTIBLE;
185	}
186	
187	function settleClaim(policy: Policy, damages: Damage[]): StepResult {
188	  // Each damage is settled against a distinct insured item, so a policy
189	  // covering one sword cannot answer two sword damages.
190	  const available = [...policy.items];
191	  const desired = damages.reduce((sum, damage) => {
192	    if (damage.amount < 0) {
193	      throw new Error(`Damage amount must not be negative: ${damage.amount}`);
194	    }
195	
196	    const index = available.findIndex((item) => item.type === damage.itemType);
197	    if (index === -1) {
198	      throw new Error(
199	        `The policy does not cover a damaged item of type "${damage.itemType}"`,
200	      );
201	    }
202	
203	    const [item] = available.splice(index, 1);
204	    return sum + payoutFor(damage, item);
205	  }, 0);
206	  const payout = Math.floor(Math.min(desired, policy.remainingCap));
207	
208	  policy.remainingCap -= payout;
209	  return { payout, remainingCap: policy.remainingCap };
210	}
211	
212	export function runScenario(scenario: Scenario): { results: StepResult[] } {
213	  const policies = new Map<number, Policy>();
214	
215	  const results = scenario.steps.map((step, index): StepResult => {
216	    if (step.op === 'claim') {
217	      const policy = policies.get(step.policy)!;
218	      return settleClaim(policy, step.incident.damages);
219	    }
220	
221	    const premium = quotePremium(
222	      step.items,
223	      scenario.customer,
224	      policies.size > 0,
225	    );
226	    const insuranceSum = step.items.reduce(
227	      (sum, item) => sum + insuranceValueOf(item),
228	      0,
229	    );
230	    policies.set(index, {
231	      items: step.items,
232	      remainingCap: insuranceSum * CAP_FACTOR,
233	    });
234	
235	    return { premium };
236	  });
237	
238	  return { results };
239	}
