4	async function readStdin(): Promise<string> {
5	  const chunks: Buffer[] = [];
6	  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
7	  return Buffer.concat(chunks).toString('utf8');
8	}
9	
10	async function main(): Promise<void> {
11	  const scenario = JSON.parse(await readStdin()) as Scenario;
12	  process.stdout.write(JSON.stringify(runScenario(scenario)));
13	}
14	
15	main().catch((error: unknown) => {
16	  process.stderr.write(`${error instanceof Error ? error.message : error}\n`);
17	  process.exitCode = 1;
18	});
